&quot;);<br>   }<br>+  <br>+}<br> <br>-  # 3. Add-regime loop<br>-  m &lt;- 0;<br>-  while (increase) {<br>+# Tests (within the LM framework), being the null hypothesis H_0 that the<br>+#    model &#39;object&#39; is complex enough and the alternative H_1 that an extra<br>+#    regime should be considered.<br>+#<br>+# object: a STAR model already built with at least 2 regimes.<br>+# gmatrix: the gradient matrix obtained by using computeGradient()<br>+# rob: boolean indicating if robust tests should be used or not.<br>+# sig: significance level of the tests<br>+# <br>+# returns a list containing the p-value of the F statistic and a boolean,<br>+#      true if there is some remaining nonlinearity and false otherwise.<br>+addRegime.star &lt;- function(object, gmatrix, rob=FALSE, sig=0.05, trace = TRUE, ...)<br>+{<br>+<br>+  e &lt;-  object$residuals;<br>+  s_t &lt;- object$model.specific$thVar;<br>+  nG &lt;- NCOL(gmatrix);<br>+  normG &lt;- norm(Matrix(G * e))<br>+<br>+  # Compute the rank of G&#39; * G<br>+  G2 &lt;- t(G) %*% G;<br>+  s &lt;- svd(G2);<br>+  tol &lt;- max(dim(G2)) * s[1]$d * 2.2204e-16<br>+  qr(G2, tol)$rank<br>+#  rG &lt;- sum(svd(G2)$d &gt; tol);<br>+<br>+  if (normG &gt; 1e+6) {<br>+    if(rG &lt; nG) {<br>+      PCtmp &lt;- princomp(G);<br>+      PC &lt;- PCtmp$loadings;<br>+#      GPCA &lt;- PCtmp$scores;<br>+      lambda &lt;- cumsum(PCtmp$sdev^2 / sum(PCtmp$sdev^2));<br>+      indmin &lt;- min(which(lambda&gt; 0.99999));<br>+      GPCA &lt;- t(PC%*%t(G));<br>+      GPCA &lt;- GPCA[, 1:indmin];<br>+      b &lt;- solve(t(GPCA) %*% GPCA) %*% t(GPCA) %*% e;<br>+      u &lt;-  e - GPCA %*% b;<br>+      xH0 &lt;- GPCA;<br>+    } else {<br>+      b &lt;- solve(t(G) %*% G) %*% t(G) %*% e;<br>+      u &lt;- e - G %*% b;<br>+      xH0 &lt;- G;<br>+    }<br>+  } else {<br>+    u &lt;- e;<br>+    if(rG &lt; nG) {<br>+      PCtmp &lt;- princomp(G);<br>+      PC &lt;- PCtmp$loadings;<br>+#      GPCA &lt;- PCtmp$scores;<br>+      lambda &lt;- cumsum(PCtmp$sdev^2 / sum(PCtmp$sdev^2));<br>+      indmin &lt;- min(which(lambda&gt; 0.99999));<br>+      GPCA &lt;- t(PC%*%t(G));<br>+      GPCA &lt;- GPCA[, 1:indmin];<br>+      xH0 &lt;- GPCA;<br>+    } else {<br>+      xH0 = G;<br>+    }<br>+  }<br> <br>-    m &lt;- m + 1;<br>+  SSE0 &lt;- sum(u^2);<br> <br>-    estimateParams();<br>-    addRegime();<br>-    <br>+  # Regressors under the alternative:<br>+  xx &lt;- object$str$xx;<br>+  if (object$model.specific$externThVar) {<br>+    x_t &lt;- cbind(1, xx);<br>+    tmp &lt;- rep(s_t, NCOL(x_t))<br>+    dim(tmp) &lt;- c(length(s_t), NCOL(x_t))<br>+    xH1 &lt;- cbind(x_t * tmp, x_t * (tmp^2), x_t * (tmp^3))<br>+  } else {<br>+    tmp &lt;- rep(s_t, NCOL(xx))<br>+    dim(tmp) &lt;- c(length(s_t), NCOL(xx))<br>+    xH1 &lt;- cbind(xx * tmp, xx * (tmp^2), xx * (tmp^3))<br>+  }<br>+<br>+  Z &lt;- cbind(xH0, xH1)<br>+<br>+  # Standarize the regressors<br>+  nZ &lt;- NCOL(Z);<br>+  sdZ &lt;- sd(Z)<br>+  dim(sdZ) &lt;- c(1, nZ)<br>+  sdZ &lt;- kronecker(matrix(1, n.used, 1), sdZ) # repeat sdZ n.used rows<br>+  Z[,2:nZ] &lt;- Z[,2:nZ] / sdZ[,2:nZ]<br>+<br>+  # Nonlinear model (Alternative hypothesis)<br>+  c &lt;- solve(t(Z) %*% Z) %*% t(Z) %*% u;<br>+  v &lt;- u - Z %*% c;<br>+  SSE &lt;- sum(v^2);<br>+<br>+  nxH0 &lt;- NCOL(xH0);<br>+  nxH1 &lt;- NCOL(xH1);<br>+  <br>+  # Compute the third order statistic<br>+  F = ((SSE0 - SSE) / nxH1) / (SSE / (n.used - nxH0 - nxH1));<br>+<br>+  pValue &lt;- pf(F, nxH1, n.used - nxH0 - nxH1, lower.tail = FALSE);<br>+#  cat(&quot;F statistic, method 1:&quot;, pValue,&quot;
&quot;)  <br>+<br>+  if (pValue &lt; sig) {<br>+    return(list(remainingNonLinearity = FALSE, pValue = pValue));<br>+  }<br>+  else {<br>+    return(list(remainingNonLinearity = TRUE, pValue = pValue));<br>+  }<br>+ <br>+}<br>+<br>+# Computes the gradient under the null hypothesis<br>+#<br>+# object: a valid STAR model.<br>+#<br>+# Returns a list of the gradients with respect to  the linear and<br>+#     nonlinear parameters<br>+computeGradient &lt;- function(object, ...)<br>+{<br>+<br>+  th &lt;- object$model.specific$phi2[,1];<br>+  gamma &lt;- object$model.specific$phi2[,2];<br>+  phi1 &lt;- object$model.specific$phi1;<br>+  n.used &lt;- NROW(object$str$xx);<br>+  s_t&lt;- object$model.specific$thVar;<br>+  x_t &lt;- cbind(1, object$str$xx);<br>+  noRegimes &lt;- object$model.specific$noRegimes;<br>+<br>+  fX &lt;- array(0, c(noRegimes - 1, n.used));<br>+  dfX &lt;- array(0, c(noRegimes - 1, n.used));<br>+  gPhi &lt;- x_t;<br>+  for (i in 1:(noRegimes - 1)) {<br>+    fX[i,] &lt;- sigmoid(gamma[i] * (s_t - th[i]));<br>+    dfX[i,] &lt;- dsigmoid(fX[i,]);<br>+    gPhi &lt;- cbind(gPhi, kronecker(matrix(1, 1, NCOL(x_t)), fX[i,]) * x_t)<br>+  }<br>+  <br>+  if (noRegimes &gt; 2) {<br>+    gGamma &lt;- array(0, c(n.used, noRegimes-1));<br>+    gTh &lt;- array(0, c(n.used, noRegimes-1))<br>+    for (i in 1:(noRegimes - 1)) {<br>+      gGamma[, i] &lt;- as.vector(x_t %*% phi1[i + 1,]) *<br>+                                                                             as.vector(dfX[i,] * (s_t - th[i]));<br>+      gTh[,i] &lt;- - as.vector(x_t %*% phi1[i+1,]) *<br>+                                                                          as.vector(gamma[i] * dfX[i,]);<br>+    }<br>+  } else {<br>+    gGamma &lt;- as.vector(x_t %*% phi1[2,]) * as.vector(dfX * (s_t - th));<br>+    gTh &lt;- - as.vector(x_t %*% phi1[2,]) * as.vector(gamma * dfX);<br>   }<br>   <br>+  return(cbind(gPhi, gGamma, gTh))<br>+<br> }<br> <br> # Estimates the parameters of a given STAR model.<br> #<br>-# object: a valid (estimated) STAR model.<br>+# object: a valid STAR model.<br> #<br> # Estimates object$model.specific$gradient<br> #                   object$model.specific$phi1<br> #                   object$model.specific$phi2<br>-estimateParams &lt;- function(object, ...)<br>+estimateParams &lt;- function(object, trace=TRUE, control=list(), ...)<br> {<br> <br>+  noRegimes &lt;- object$model.specific$noRegimes<br>+  s_t&lt;- object$model.specific$thVar;<br>+  xx &lt;- object$str$xx<br>+  yy &lt;- object$str$yy<br>+  n.used &lt;- NROW(object$str$xx);<br>+<br>+  # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #<br>   # 1.- Find promising initial values<br>-  startingValues(object)<br>+  object &lt;- startingValues(object);<br>   <br>+  # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #<br>   # 2.- Estimate nonlinear parameters<br>+<br>+  # Sum of squares function<br>+  # phi2: vector of parameters<br>+  SS &lt;- function(phi2) {<br>+    dim(phi2) &lt;- c(noRegimes - 1, 2)<br>+    th &lt;- phi2[,1]<br>+    gamma &lt;- phi2[,2]<br>+    <br>+    # We fix the linear parameters here, before optimizing the nonlinear.<br>+    x_t &lt;- cbind(1, xx)<br>+    tmp &lt;- x_t;<br>+#  if (noRegimes &gt; 2) {<br>+    for(i in 1:(noRegimes - 1)) {<br>+      tmp &lt;- cbind(tmp, x_t * sigmoid(gamma[i] * (s_t - th[i])))<br>+    }<br>+#  }<br>+#  else {<br>+#    tmp &lt;- cbind(tmp, x_t * sigmoid(gamma * (s_t - th)));<br>+#  }<br>+    <br>+    newPhi1 &lt;- lm(yy ~ . - 1, data.frame(tmp))$coefficients;<br>+    dim(newPhi1) &lt;- c(noRegimes, NCOL(x_t))<br>+        <br>+    <br>+    # Return the sum of squares<br>+    local &lt;- array(0, c(noRegimes, n.used))<br>+    local[1,] &lt;- x_t %*% newPhi1[1,]<br>+    for (i in 2:noRegimes) <br>+      local[i,] &lt;-<br>+        (x_t %*% newPhi1[i,]) * sigmoid(gamma[i - 1] * (s_t - th[i - 1]))<br>+    <br>+    y.hat &lt;- apply(local, 2, sum)<br>+    crossprod(yy - y.hat)<br>+  